const queryClient = new QueryClient();
type Store = { elections: Election[]; candidates: Candidate[]; voters: Voter[]; activities: Activity[]; results: Record<string, Result[]>; votedIds: string[]; addElection: (data: Partial<Election>) => void; updateElection: (id: string, data: Partial<Election>) => void; deleteElection: (id: string) => void; addCandidate: (data: Omit<Candidate, 'id'>) => void; updateCandidate: (id: string, data: Partial<Candidate>) => void; deleteCandidate: (id: string) => void; submitVote: (id: string, candidateId: string) => void; };
const StoreContext = createContext<Store | null>(null);
const useStore = () => useContext(StoreContext)!;

function Button({ children, variant = 'primary', className = '', ...props }: { children: ReactNode; variant?: 'primary'|'secondary'|'ghost'|'danger'; className?: string; [key: string]: unknown }) {
  const styles = { primary:'bg-[hsl(var(--primary))] text-white hover:bg-[#18365f]', secondary:'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))] hover:bg-[#dbe7ef]', ghost:'bg-transparent text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--foreground))]', danger:'bg-[#fff1f0] text-[#a53531] hover:bg-[#ffe3e1]' };
  return <button className={`inline-flex items-center justify-center gap-2 rounded-md px-4 py-2.5 text-sm font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} {...props}>{children}</button>;
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral'|'active'|'success'|'blue'|'danger' }) {
  const c = { neutral:'bg-slate-100 text-slate-600', active:'bg-[#e3f2f6] text-[#17617a]', success:'bg-[#e4f2eb] text-[#286649]', blue:'bg-[#e5ebf7] text-[#244c84]', danger:'bg-[#fae6e3] text-[#a13832]' };
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold ${c[tone]}`}><span className={`h-1.5 w-1.5 rounded-full ${tone==='success'?'bg-[#37805b]':tone==='danger'?'bg-[#ba443e]':tone==='active'?'bg-[#2085a4]':'bg-current opacity-60'}`} />{children}</span>;
}
function Brand({ inverse = false }: { inverse?: boolean }) {
  return <Link href="/" data-testid="link-brand" className="flex items-center gap-3"><span className={`grid h-9 w-9 place-items-center rounded-md ${inverse ? 'bg-[#2d7894]' : 'bg-[hsl(var(--primary))]'}`}><ShieldCheck className="h-5 w-5 text-white" /></span><span className={`font-display text-xl font-bold tracking-tight ${inverse ? 'text-white' : 'text-[hsl(var(--primary))]'}`}>VoteSecure</span></Link>;
}
function PublicNav() {
  const [open,setOpen] = useState(false);
  return <header className="border-b border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8"><Brand /><nav className="hidden items-center gap-7 md:flex"><a href="#how-it-works" className="text-sm font-medium text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]" data-testid="link-how">How it works</a><a href="#trust" className="text-sm font-medium text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]" data-testid="link-trust">Our promise</a><Link href="/admin/login" className="text-sm font-medium text-[hsl(var(--muted-foreground))]" data-testid="link-admin-entry">Administration</Link></nav><div className="hidden items-center gap-2 sm:flex"><Link href="/login" data-testid="link-login"><Button variant="ghost">Sign in</Button></Link><Link href="/register" data-testid="link-register"><Button>Register to vote <ArrowRight className="h-4 w-4" /></Button></Link></div><button onClick={()=>setOpen(!open)} className="rounded-md p-2 md:hidden" data-testid="button-mobile-menu"><Menu className="h-5 w-5" /></button></div>{open&&<div className="border-t px-5 py-4 md:hidden"><div className="grid gap-3"><a href="#how-it-works" onClick={()=>setOpen(false)} className="py-2 text-sm" data-testid="link-mobile-how">How it works</a><Link href="/login" onClick={()=>setOpen(false)} className="py-2 text-sm" data-testid="link-mobile-login">Sign in</Link><Link href="/register" onClick={()=>setOpen(false)} className="py-2 text-sm font-semibold" data-testid="link-mobile-register">Register to vote</Link></div></div>}</header>;
}
function PublicLayout({ children }: { children: ReactNode }) { return <div className="min-h-[100dvh] bg-[hsl(var(--background))]"><PublicNav />{children}<footer className="border-t bg-[#edf3f6]"><div className="mx-auto flex max-w-7xl flex-col gap-4 px-5 py-8 text-sm text-[hsl(var(--muted-foreground))] sm:flex-row sm:items-center sm:justify-between lg:px-8"><Brand /><span>© 2026 VoteSecure. A clearer way to participate.</span><div className="flex gap-4"><a href="#trust" data-testid="link-privacy">Privacy</a><a href="#trust" data-testid="link-accessibility">Accessibility</a></div></div></footer></div>; }

const voterNav = [{href:'/voter/dashboard',label:'Overview',icon:LayoutDashboard},{href:'/voter/elections',label:'Elections',icon:Vote},{href:'/voter/confirmation',label:'My activity',icon:ClipboardCheck}];
const adminNav = [{href:'/admin/dashboard',label:'Dashboard',icon:LayoutDashboard},{href:'/admin/elections',label:'Elections',icon:CalendarDays},{href:'/admin/candidates',label:'Candidates',icon:Users},{href:'/admin/voters',label:'Voters',icon:UserCheck},{href:'/admin/results',label:'Results',icon:BarChart3}];
function SideNav({ admin = false, mobileOpen, onClose }: { admin?: boolean; mobileOpen?: boolean; onClose?: ()=>void }) {
  const [location] = useLocation(); const links = admin ? adminNav : voterNav;
  return <aside className={`${mobileOpen?'fixed inset-y-0 left-0 z-50 flex':'hidden'} w-64 flex-col bg-[hsl(var(--sidebar))] p-5 text-[hsl(var(--sidebar-foreground))] md:flex`}><div className="mb-10 flex items-center justify-between"><Brand inverse />{onClose&&<button onClick={onClose} className="md:hidden" data-testid="button-close-menu"><X className="h-5 w-5" /></button>}</div><p className="label-caps mb-3 text-[#9eb9cb]">{admin?'Administration':'Voter portal'}</p><nav className="grid gap-1">{links.map(({href,label,icon:Icon})=><Link key={href} href={href} onClick={onClose} data-testid={`link-nav-${label.toLowerCase()}`} className={`flex items-center gap-3 rounded-md px-3 py-3 text-sm font-medium transition-colors ${location===href?'bg-[hsl(var(--sidebar-accent))] text-white':'text-[#c0d3df] hover:bg-white/10 hover:text-white'}`}><Icon className="h-[18px] w-[18px]" />{label}</Link>)}</nav><div className="mt-auto border-t border-white/15 pt-4"><Link href={admin?'/admin/login':'/login'} data-testid="link-shell-settings" className="flex items-center gap-3 rounded-md px-3 py-3 text-sm text-[#c0d3df] hover:bg-white/10"><Settings className="h-[18px] w-[18px]" />Settings</Link><Link href="/" data-testid="link-shell-logout" className="flex items-center gap-3 rounded-md px-3 py-3 text-sm text-[#c0d3df] hover:bg-white/10"><LogOut className="h-[18px] w-[18px]" />Sign out</Link></div></aside>;
}
function AppShell({ children, admin = false }: { children: ReactNode; admin?: boolean }) {
  const [mobileOpen,setMobileOpen] = useState(false);
  return <div className="flex min-h-[100dvh] bg-[hsl(var(--background))]"><SideNav admin={admin} mobileOpen={mobileOpen} onClose={()=>setMobileOpen(false)} /><div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b bg-[hsl(var(--card))]/95 px-5 backdrop-blur lg:px-8"><button onClick={()=>setMobileOpen(true)} className="mr-3 rounded-md p-2 md:hidden" data-testid="button-open-menu"><Menu className="h-5 w-5" /></button><div className="hidden md:block"><p className="label-caps text-[hsl(var(--muted-foreground))]">{admin?'Civic administration':'Welcome back'}</p><p className="font-display text-xl font-semibold">{admin?'Stewardship dashboard':'Your voting space'}</p></div><div className="ml-auto flex items-center gap-4"><button className="relative rounded-md p-2 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]" data-testid="button-notifications"><Bell className="h-5 w-5" /><span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-[#2d7894]" /></button><div className="hidden items-center gap-2 border-l pl-4 sm:flex"><span className="grid h-8 w-8 place-items-center rounded-full bg-[#dbeaf0] text-sm font-bold text-[hsl(var(--primary))]">{admin?'AD':'AM'}</span><span className="text-sm font-semibold">{admin?'Alex Duarte':'Avery Morgan'}</span><ChevronDown className="h-4 w-4 text-[hsl(var(--muted-foreground))]" /></div></div></header><main className="mx-auto max-w-[1440px] p-5 lg:p-8">{children}</main></div></div>;
}
function SectionTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow&&<p className="label-caps mb-2 text-[#2d7894]">{eyebrow}</p>}<h1 className="font-display text-3xl font-bold tracking-tight text-[hsl(var(--primary))] sm:text-4xl">{title}</h1>{description&&<p className="mt-2 max-w-2xl text-[hsl(var(--muted-foreground))]">{description}</p>}</div>{action}</div>; }
function StatCard({ label, value, note, icon:Icon, tone='blue' }: { label:string; value:string; note:string; icon:typeof Vote; tone?:string }) { return <div className="border bg-[hsl(var(--card))] p-5 shadow-[var(--shadow-sm)]"><div className="flex items-start justify-between"><div><p className="text-sm text-[hsl(var(--muted-foreground))]">{label}</p><p className="mt-2 text-3xl font-bold tracking-tight text-[hsl(var(--primary))]">{value}</p></div><span className={`grid h-10 w-10 place-items-center rounded-md ${tone==='green'?'bg-[#e4f2eb] text-[#357a58]':'bg-[#e3f0f5] text-[#28758f]'}`}><Icon className="h-5 w-5" /></span></div><p className="mt-4 text-xs text-[hsl(var(--muted-foreground))]">{note}</p></div>; }

function Home() { return <PublicLayout><section className="page-grid relative overflow-hidden"><div className="mx-auto grid max-w-7xl items-center gap-12 px-5 py-20 lg:grid-cols-[1.05fr_.95fr] lg:px-8 lg:py-28"><div className="animate-enter"><div className="mb-6 flex items-center gap-2 text-sm font-semibold text-[#28758f]"><span className="h-2 w-2 rounded-full bg-[#37805b]" />A public service for participation</div><h1 className="font-display max-w-2xl text-5xl font-bold leading-[1.02] tracking-[-.03em] text-[hsl(var(--primary))] sm:text-7xl">Your voice, <em className="font-normal text-[#28758f]">verified.</em></h1><p className="mt-7 max-w-xl text-lg leading-8 text-[hsl(var(--muted-foreground))]">VoteSecure gives students and community members a clear, private path from registration to recorded ballot.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/register" data-testid="link-hero-register"><Button className="px-5 py-3">Register to vote <ArrowRight className="h-4 w-4" /></Button></Link><Link href="/login" data-testid="link-hero-login"><Button variant="secondary" className="px-5 py-3">I have an account</Button></Link></div><div className="mt-10 flex items-center gap-3 text-sm text-[hsl(var(--muted-foreground))]"><ShieldCheck className="h-5 w-5 text-[#37805b]" />Private by design. Your choice is never shown in your activity.</div></div><div className="animate-enter-delay relative"><div className="absolute -inset-5 bg-[#dcecf0] opacity-60 blur-3xl" /><div className="relative border border-[#bdd5df] bg-[#f8fcfc] p-7 shadow-[var(--shadow-md)]"><div className="flex items-center justify-between border-b pb-5"><div><p className="label-caps text-[#28758f]">Today’s civic moment</p><p className="mt-1 font-display text-2xl font-semibold text-[hsl(var(--primary))]">One clear choice.</p></div><span className="grid h-10 w-10 place-items-center rounded-full bg-[#e4f2eb] text-[#357a58]"><CheckCircle2 className="h-5 w-5" /></span></div><div className="py-7"><div className="mb-3 flex justify-between text-sm"><span className="font-semibold">Student Council Election 2026</span><Badge tone="active">Open now</Badge></div><div className="h-2 overflow-hidden bg-[#dbe7ea]"><div className="h-full w-[65%] bg-[#28758f]" /></div><div className="mt-3 flex justify-between text-xs text-[hsl(var(--muted-foreground))]"><span>817 ballots recorded</span><span>3 days left</span></div></div><div className="grid grid-cols-3 gap-2 border-t pt-5 text-center"><div><p className="text-xl font-bold text-[hsl(var(--primary))]">01</p><p className="text-xs text-[hsl(var(--muted-foreground))]">select</p></div><div><p className="text-xl font-bold text-[hsl(var(--primary))]">02</p><p className="text-xs text-[hsl(var(--muted-foreground))]">review</p></div><div><p className="text-xl font-bold text-[hsl(var(--primary))]">03</p><p className="text-xs text-[hsl(var(--muted-foreground))]">record</p></div></div></div></div></div></section><section id="trust" className="mx-auto max-w-7xl px-5 py-20 lg:px-8"><div className="grid gap-8 lg:grid-cols-[.8fr_1.2fr]"><div><p className="label-caps mb-3 text-[#28758f]">Our promise</p><h2 className="font-display max-w-md text-4xl font-bold leading-tight text-[hsl(var(--primary))]">Confidence at every step.</h2><p className="mt-4 max-w-md leading-7 text-[hsl(var(--muted-foreground))]">No jargon, no guesswork. Every screen explains what is happening and what happens next.</p></div><div className="grid gap-4 sm:grid-cols-3"><InfoTile icon={ShieldCheck} title="Private" text="We show participation status, never your candidate choice."/><InfoTile icon={Globe2} title="Accessible" text="Designed for keyboard, mobile, and everyday connection speeds."/><InfoTile icon={FileText} title="Transparent" text="A receipt confirms your ballot without exposing how you voted."/></div></div></section><section id="how-it-works" className="bg-[#e8f0f3]"><div className="mx-auto max-w-7xl px-5 py-20 lg:px-8"><div className="mb-12 max-w-xl"><p className="label-caps mb-3 text-[#28758f]">How it works</p><h2 className="font-display text-4xl font-bold text-[hsl(var(--primary))]">A calm three-step process.</h2></div><div className="grid gap-0 border-y border-[#cbdbe1] md:grid-cols-3"><Step n="01" title="Find your election" text="See what is open, what is coming up, and when each voting window closes."/><Step n="02" title="Make your choice" text="Read candidate profiles, choose once, and review before anything is recorded."/><Step n="03" title="Keep your receipt" text="Get a private ballot reference so you can trust that your participation is counted."/></div></div></section><section className="mx-auto max-w-7xl px-5 py-20 lg:px-8"><div className="flex flex-col items-start justify-between gap-8 border-l-4 border-[#28758f] pl-7 sm:flex-row sm:items-center"><div><p className="font-display text-3xl font-bold text-[hsl(var(--primary))]">Ready when you are.</p><p className="mt-2 text-[hsl(var(--muted-foreground))]">Participation starts with a single registration.</p></div><Link href="/register" data-testid="link-bottom-register"><Button>Start registration <ArrowRight className="h-4 w-4" /></Button></Link></div></section></PublicLayout>; }
function InfoTile({ icon:Icon, title, text }: { icon:typeof Vote; title:string; text:string }) { return <div className="border bg-[hsl(var(--card))] p-5"><Icon className="mb-6 h-6 w-6 text-[#28758f]" /><h3 className="font-semibold text-[hsl(var(--primary))]">{title}</h3><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{text}</p></div>; }
function Step({ n,title,text }: { n:string; title:string; text:string }) { return <div className="border-r border-[#cbdbe1] px-2 py-7 last:border-0 md:px-7"><span className="font-mono text-sm font-bold text-[#28758f]">{n}</span><h3 className="mt-6 font-display text-2xl font-bold text-[hsl(var(--primary))]">{title}</h3><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{text}</p></div>; }

function AuthLayout({ children, admin=false }: { children:ReactNode; admin?:boolean }) { return <div className="grid min-h-[100dvh] lg:grid-cols-[.85fr_1.15fr]"><div className={`hidden flex-col justify-between p-10 lg:flex ${admin?'bg-[hsl(var(--primary))]':'bg-[#e8f1f3]'}`}><Brand inverse={admin}/><div className="max-w-md">{admin?<><p className="label-caps text-[#9eb9cb]">Trusted stewardship</p><h2 className="mt-4 font-display text-5xl font-bold leading-tight text-white">Good civic systems are easy to understand.</h2><p className="mt-6 leading-7 text-[#c0d3df]">A focused workspace for the people responsible for making every election clear, fair, and accountable.</p></>:<><p className="label-caps text-[#28758f]">Welcome to VoteSecure</p><h2 className="mt-4 font-display text-5xl font-bold leading-tight text-[hsl(var(--primary))]">Participation should feel straightforward.</h2><p className="mt-6 leading-7 text-[hsl(var(--muted-foreground))]">Your ballot is yours. We make the path to casting it simple and private.</p></>}</div><div className={`text-sm ${admin?'text-[#9eb9cb]':'text-[hsl(var(--muted-foreground))]'}`}>Secure access · Clear information · Human support</div></div><div className="flex flex-col bg-[hsl(var(--background))]"><div className="flex items-center justify-between px-5 py-5 lg:justify-end lg:px-12"><div className="lg:hidden"><Brand inverse={admin}/></div><Link href="/" className="text-sm text-[hsl(var(--muted-foreground))]" data-testid="link-auth-home"><ArrowLeft className="mr-2 inline h-4 w-4" />Back home</Link></div><div className="mx-auto flex w-full max-w-lg flex-1 items-center px-5 py-8 lg:px-10">{children}</div></div></div>; }
function Login({ admin=false }: { admin?:boolean }) { const [,setLocation] = useLocation(); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [error,setError]=useState(''); const submit=(e:React.FormEvent)=>{e.preventDefault(); if(!email||!password){setError('Enter your email and password to continue.');return;} setLocation(admin?'/admin/dashboard':'/voter/dashboard');}; return <AuthLayout admin={admin}><div className="w-full"><p className="label-caps mb-3 text-[#28758f]">{admin?'Administration':'Voter access'}</p><h1 className="font-display text-4xl font-bold text-[hsl(var(--primary))]">{admin?'Sign in to administration':'Welcome back'}</h1><p className="mt-3 text-[hsl(var(--muted-foreground))]">{admin?'Manage elections with care and clarity.':'Access your elections and voting activity.'}</p><form onSubmit={submit} className="mt-8 grid gap-5"><label className="grid gap-2 text-sm font-semibold">Email address<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder={admin?'admin@votesecure.org':'you@example.org'} className="h-12 rounded-md border bg-[hsl(var(--card))] px-3 font-normal outline-none focus:border-[#28758f]" data-testid="input-login-email"/></label><label className="grid gap-2 text-sm font-semibold">Password<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password" className="h-12 rounded-md border bg-[hsl(var(--card))] px-3 font-normal outline-none focus:border-[#28758f]" data-testid="input-login-password"/></label>{error&&<p className="text-sm text-[#a53531]" data-testid="status-login-error">{error}</p>}<Button className="mt-2 h-12" data-testid="button-submit-login"><LogIn className="h-4 w-4"/>{admin?'Sign in securely':'Sign in'}</Button></form>{!admin&&<p className="mt-7 text-center text-sm text-[hsl(var(--muted-foreground))]">New to VoteSecure? <Link href="/register" className="font-semibold text-[#28758f]" data-testid="link-login-register">Register here</Link></p>}{admin&&<p className="mt-7 text-center text-sm text-[hsl(var(--muted-foreground))]">Need voter access? <Link href="/login" className="font-semibold text-[#28758f]" data-testid="link-admin-voter-login">Voter sign in</Link></p>}</div></AuthLayout>; }
function Register() { const [,setLocation]=useLocation(); const [form,setForm]=useState({name:'',email:'',password:'',confirm:''}); const [error,setError]=useState(''); const strength=form.password.length>11?3:form.password.length>7?2:form.password.length>0?1:0; const update=(key:string)=>(e:React.ChangeEvent<HTMLInputElement>)=>setForm({...form,[key]:e.target.value}); const submit=(e:React.FormEvent)=>{e.preventDefault(); if(!form.name||!form.email||form.password.length<8||form.password!==form.confirm){setError('Please check your details. Passwords must match and be at least 8 characters.');return;}setLocation('/voter/dashboard');}; return <AuthLayout><div className="w-full"><p className="label-caps mb-3 text-[#28758f]">Voter registration</p><h1 className="font-display text-4xl font-bold text-[hsl(var(--primary))]">Create your voter account</h1><p className="mt-3 text-[hsl(var(--muted-foreground))]">You only need a few details. Your account keeps your ballot history private.</p><form onSubmit={submit} className="mt-8 grid gap-4"><label className="grid gap-2 text-sm font-semibold">Full name<input value={form.name} onChange={update('name')} className="h-11 rounded-md border bg-[hsl(var(--card))] px-3 font-normal" placeholder="Avery Morgan" data-testid="input-register-name"/></label><label className="grid gap-2 text-sm font-semibold">Email address<input type="email" value={form.email} onChange={update('email')} className="h-11 rounded-md border bg-[hsl(var(--card))] px-3 font-normal" placeholder="you@example.org" data-testid="input-register-email"/></label><label className="grid gap-2 text-sm font-semibold">Password<input type="password" value={form.password} onChange={update('password')} className="h-11 rounded-md border bg-[hsl(var(--card))] px-3 font-normal" placeholder="At least 8 characters" data-testid="input-register-password"/><span className="flex gap-1">{[1,2,3].map(n=><span key={n} className={`h-1 flex-1 ${strength>=n?'bg-[#37805b]':'bg-[#dbe2e5]'}`} />)}</span><span className="text-xs font-normal text-[hsl(var(--muted-foreground))]">{strength===3?'Strong password':strength===2?'Good — add a few more characters':'Use 8 or more characters'}</span></label><label className="grid gap-2 text-sm font-semibold">Confirm password<input type="password" value={form.confirm} onChange={update('confirm')} className="h-11 rounded-md border bg-[hsl(var(--card))] px-3 font-normal" data-testid="input-register-confirm"/></label>{error&&<p className="text-sm text-[#a53531]" data-testid="status-register-error">{error}</p>}<Button className="mt-3 h-12" data-testid="button-submit-register">Create account <ArrowRight className="h-4 w-4"/></Button></form><p className="mt-6 text-center text-sm text-[hsl(var(--muted-foreground))]">Already registered? <Link href="/login" className="font-semibold text-[#28758f]" data-testid="link-register-login">Sign in</Link></p></div></AuthLayout>; }

function VoterDashboard() { const {elections,activities}=useStore(); const active=elections.filter(e=>e.status==='active'); return <AppShell><SectionTitle eyebrow="Voter overview" title="Good morning, Avery." description="Here’s what is happening in your civic space." action={<Link href="/voter/elections" data-testid="link-dashboard-directory"><Button>Browse elections <ArrowRight className="h-4 w-4"/></Button></Link>}/><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Open elections" value={String(active.length).padStart(2,'0')} note="One needs your attention" icon={Vote}/><StatCard label="Ballots recorded" value="04" note="Across your participation history" icon={ClipboardCheck} tone="green"/><StatCard label="Next closing date" value="20 Feb" note="Student Council Election" icon={Clock3}/></div><div className="mt-8 grid gap-6 lg:grid-cols-[1.35fr_.65fr]"><div className="border bg-[hsl(var(--card))] p-6 shadow-[var(--shadow-sm)]"><div className="mb-5 flex items-center justify-between"><div><p className="label-caps text-[#28758f]">Needs your attention</p><h2 className="mt-1 font-display text-2xl font-bold text-[hsl(var(--primary))]">Active elections</h2></div><Link href="/voter/elections" className="text-sm font-semibold text-[#28758f]" data-testid="link-dashboard-see-all">See all</Link></div>{active.map(e=><ElectionRow key={e.id} election={e} />)}</div><div className="border bg-[hsl(var(--primary))] p-6 text-white"><p className="label-caps text-[#a8cfdb]">A simple reminder</p><h2 className="mt-4 font-display text-2xl font-bold">Your vote is private.</h2><p className="mt-3 text-sm leading-6 text-[#c6dae3]">VoteSecure records that you participated, never which candidate you selected.</p><div className="mt-8 border-t border-white/20 pt-5 text-sm text-[#c6dae3]"><ShieldCheck className="mr-2 inline h-4 w-4 text-[#7bc39b]"/>End-to-end ballot privacy</div></div></div><div className="mt-8 border bg-[hsl(var(--card))] p-6"><div className="mb-4 flex items-center gap-3"><ActivityIcon className="h-5 w-5 text-[#28758f]"/><h2 className="font-display text-2xl font-bold text-[hsl(var(--primary))]">Recent activity</h2></div>{activities.slice(0,3).map(a=><ActivityRow activity={a} key={a.id}/>)}</div></AppShell>; }
function ElectionRow({ election }: { election:Election }) { return <div className="flex flex-col gap-4 border-t py-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-3"><h3 className="font-semibold text-[hsl(var(--primary))]">{election.title}</h3><Badge tone={election.status==='active'?'active':'neutral'}>{election.status==='active'?'Open now':'Upcoming'}</Badge></div><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{election.votes} people have voted · closes {election.endDate}</p></div><Link href={`/voter/elections/${election.id}`} data-testid={`link-election-${election.id}`}><Button variant="secondary">View election <ArrowRight className="h-4 w-4"/></Button></Link></div>; }
function ActivityRow({ activity }: {activity:Activity}) { return <div className="flex items-center gap-4 border-t py-4"><span className="grid h-9 w-9 place-items-center rounded-full bg-[#e4f2eb] text-[#357a58]"><Check className="h-4 w-4"/></span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{activity.label}</p><p className="truncate text-sm text-[hsl(var(--muted-foreground))]">{activity.detail}</p></div><time className="text-xs text-[hsl(var(--muted-foreground))]">{activity.timestamp}</time></div>; }

function ElectionDirectory() { const {elections}=useStore(); const [search,setSearch]=useState('');const [filter,setFilter]=useState('all');const [sort,setSort]=useState('soon'); const filtered=useMemo(()=>elections.filter(e=>(filter==='all'||e.status===filter)&&e.title.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='name'?a.title.localeCompare(b.title):a.endDate.localeCompare(b.endDate)),[elections,search,filter,sort]); return <AppShell><SectionTitle eyebrow="Election directory" title="Find your election." description="Browse current and upcoming elections in one clear list."/><div className="mb-6 flex flex-col gap-3 rounded-md border bg-[hsl(var(--card))] p-3 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-[hsl(var(--muted-foreground))]"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search elections" className="h-10 w-full rounded border bg-[hsl(var(--background))] pl-9 pr-3 text-sm" data-testid="input-election-search"/></label><div className="flex gap-2"><select value={filter} onChange={e=>setFilter(e.target.value)} className="h-10 rounded border bg-[hsl(var(--background))] px-3 text-sm" data-testid="select-election-filter"><option value="all">All statuses</option><option value="active">Open now</option><option value="upcoming">Upcoming</option><option value="ended">Ended</option></select><select value={sort} onChange={e=>setSort(e.target.value)} className="h-10 rounded border bg-[hsl(var(--background))] px-3 text-sm" data-testid="select-election-sort"><option value="soon">Closing soon</option><option value="name">Name A–Z</option></select></div></div>{filtered.length===0?<EmptyState title="No elections found" text="Try a different search or status filter."/>:<div className="grid gap-4">{filtered.map(e=><ElectionCard election={e} key={e.id}/>)}</div>}</AppShell>; }
function ElectionCard({ election }: {election:Election}) { const ended=election.status==='ended'; return <article className="border bg-[hsl(var(--card))] p-6 shadow-[var(--shadow-sm)] transition-shadow hover:shadow-[var(--shadow-md)]"><div className="flex flex-col justify-between gap-5 md:flex-row"><div className="max-w-2xl"><div className="mb-3 flex flex-wrap items-center gap-3"><Badge tone={election.status==='active'?'active':election.status==='ended'?'neutral':'blue'}>{election.status==='active'?'Open now':election.status}</Badge><span className="text-xs text-[hsl(var(--muted-foreground))]">{ended?'Closed':'Closes'} {election.endDate}</span></div><h2 className="font-display text-2xl font-bold text-[hsl(var(--primary))]">{election.title}</h2><p className="mt-2 leading-6 text-[hsl(var(--muted-foreground))]">{election.description}</p></div><div className="flex shrink-0 items-center md:items-end"><Link href={`/voter/elections/${election.id}`} data-testid={`link-directory-election-${election.id}`}><Button variant={ended?'secondary':'primary'}>{ended?'View details':'View election'} <ArrowRight className="h-4 w-4"/></Button></Link></div></div><div className="mt-6 flex flex-wrap gap-x-8 gap-y-2 border-t pt-4 text-sm text-[hsl(var(--muted-foreground))]"><span><CalendarDays className="mr-2 inline h-4 w-4 text-[#28758f]"/>{election.startDate} — {election.endDate}</span><span><Users className="mr-2 inline h-4 w-4 text-[#28758f]"/>{election.registeredVoters} registered voters</span></div></article>; }
function EmptyState({title,text}: {title:string;text:string}) { return <div className="border border-dashed bg-[hsl(var(--card))] px-6 py-14 text-center"><Search className="mx-auto h-8 w-8 text-[#7da8b7]"/><h2 className="mt-4 font-display text-2xl font-bold text-[hsl(var(--primary))]">{title}</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{text}</p></div>; }

function ElectionDetails() { const {id}=useParams();const {elections,candidates}=useStore();const election=elections.find(e=>e.id===id)||elections[0];const list=candidates.filter(c=>election.candidateIds.includes(c.id)); return <AppShell><Link href="/voter/elections" className="mb-7 inline-flex items-center gap-2 text-sm font-semibold text-[#28758f]" data-testid="link-back-elections"><ArrowLeft className="h-4 w-4"/>Back to elections</Link><div className="max-w-4xl"><div className="flex flex-wrap items-center gap-3"><Badge tone={election.status==='active'?'active':'blue'}>{election.status==='active'?'Open now':election.status}</Badge><span className="text-sm text-[hsl(var(--muted-foreground))]">{election.startDate} — {election.endDate}</span></div><h1 className="mt-4 font-display text-4xl font-bold text-[hsl(var(--primary))] sm:text-5xl">{election.title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-[hsl(var(--muted-foreground))]">{election.description}</p>{election.status==='active'&&<Link href={`/voter/vote/${election.id}`} data-testid="link-start-vote"><Button className="mt-7">Start your ballot <ArrowRight className="h-4 w-4"/></Button></Link>}</div><div className="mt-14"><div className="mb-6"><p className="label-caps text-[#28758f]">The ballot</p><h2 className="mt-1 font-display text-3xl font-bold text-[hsl(var(--primary))]">Meet the candidates</h2></div><div className="grid gap-4 md:grid-cols-2">{list.map(c=><CandidateProfile candidate={c} key={c.id}/>)}</div></div></AppShell>; }
function CandidateProfile({candidate}: {candidate:Candidate}) { return <article className="border bg-[hsl(var(--card))] p-5"><div className="flex gap-4"><div className="grid h-14 w-14 shrink-0 place-items-center rounded-full text-lg font-bold text-white" style={{backgroundColor:candidate.color}}>{candidate.name.split(' ').map(n=>n[0]).join('')}</div><div><h3 className="font-display text-xl font-bold text-[hsl(var(--primary))]">{candidate.name}</h3><p className="text-sm font-semibold text-[#28758f]">{candidate.party}</p></div></div><p className="mt-5 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{candidate.description}</p></article>; }

function VotePage() { const {id}=useParams();const [,setLocation]=useLocation();const {elections,candidates,votedIds,submitVote}=useStore();const election=elections.find(e=>e.id===id)||elections[0];const list=candidates.filter(c=>election.candidateIds.includes(c.id));const [selected,setSelected]=useState('');const [step,setStep]=useState(1);const [modal,setModal]=useState(false);const [done,setDone]=useState(votedIds.includes(election.id));if(done)return <AppShell><div className="mx-auto max-w-2xl py-14 text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#e4f2eb] text-[#357a58]"><CheckCircle2 className="h-8 w-8"/></span><p className="label-caps mt-7 text-[#28758f]">Ballot submitted</p><h1 className="mt-2 font-display text-4xl font-bold text-[hsl(var(--primary))]">Your vote has been recorded.</h1><p className="mx-auto mt-4 max-w-md leading-7 text-[hsl(var(--muted-foreground))]">You have already participated in this election during this session. Your candidate selection is never displayed here.</p><Link href="/voter/confirmation" data-testid="link-vote-confirmation"><Button className="mt-8">View private receipt <ArrowRight className="h-4 w-4"/></Button></Link></div></AppShell>;const chosen=list.find(c=>c.id===selected);return <AppShell><div className="mx-auto max-w-3xl"><Link href={`/voter/elections/${election.id}`} className="mb-7 inline-flex items-center gap-2 text-sm font-semibold text-[#28758f]" data-testid="link-back-election-detail"><ArrowLeft className="h-4 w-4"/>Back to election</Link><div className="mb-9"><p className="label-caps text-[#28758f]">Private ballot · step {step} of 2</p><h1 className="mt-2 font-display text-4xl font-bold text-[hsl(var(--primary))]">{step===1?'Make your choice':'Review your ballot'}</h1><p className="mt-3 text-[hsl(var(--muted-foreground))]">{election.title}</p></div>{step===1?<><div className="grid gap-3">{list.map(c=><label key={c.id} className={`flex cursor-pointer items-center gap-4 border bg-[hsl(var(--card))] p-5 transition-colors ${selected===c.id?'border-[#28758f] bg-[#f2fafb]':'hover:border-[#8bb7c2]'}`}><input type="radio" name="candidate" value={c.id} checked={selected===c.id} onChange={()=>setSelected(c.id)} className="h-5 w-5 accent-[#28758f]" data-testid={`input-candidate-${c.id}`}/><span className="grid h-11 w-11 place-items-center rounded-full text-sm font-bold text-white" style={{backgroundColor:c.color}}>{c.name.split(' ').map(n=>n[0]).join('')}</span><span><span className="block font-semibold text-[hsl(var(--primary))]">{c.name}</span><span className="text-sm text-[hsl(var(--muted-foreground))]">{c.party}</span></span></label>)}</div><div className="mt-7 flex items-center justify-between border-t pt-5"><span className="text-sm text-[hsl(var(--muted-foreground))]">Your choice stays private.</span><Button disabled={!selected} onClick={()=>setStep(2)} data-testid="button-review-vote">Review ballot <ArrowRight className="h-4 w-4"/></Button></div></>:<div className="border bg-[hsl(var(--card))] p-6"><div className="flex items-center justify-between border-b pb-5"><div><p className="text-sm text-[hsl(var(--muted-foreground))]">Your selection</p><p className="mt-1 font-display text-2xl font-bold text-[hsl(var(--primary))]">{chosen?.name}</p><p className="text-sm text-[hsl(var(--muted-foreground))]">{chosen?.party}</p></div><CheckCircle2 className="h-7 w-7 text-[#37805b]"/></div><p className="mt-5 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Please confirm below. Once submitted, your ballot cannot be changed. Your receipt will not include this selection.</p><div className="mt-7 flex flex-wrap justify-between gap-3"><Button variant="ghost" onClick={()=>setStep(1)} data-testid="button-edit-vote"><ArrowLeft className="h-4 w-4"/>Change choice</Button><Button onClick={()=>setModal(true)} data-testid="button-submit-vote">Submit ballot <Check className="h-4 w-4"/></Button></div></div>}{modal&&<div className="fixed inset-0 z-50 grid place-items-center bg-[#122b45]/50 p-5"><div className="w-full max-w-md border bg-[hsl(var(--card))] p-7 shadow-[var(--shadow-md)]"><div className="flex items-start justify-between"><div><p className="label-caps text-[#28758f]">One last check</p><h2 className="mt-2 font-display text-2xl font-bold text-[hsl(var(--primary))]">Submit this ballot?</h2></div><button onClick={()=>setModal(false)} data-testid="button-close-confirmation"><X className="h-5 w-5"/></button></div><p className="mt-4 text-sm leading-6 text-[hsl(var(--muted-foreground))]">This records your participation in {election.title}. Your selection stays private and cannot be changed after submission.</p><div className="mt-7 flex justify-end gap-3"><Button variant="ghost" onClick={()=>setModal(false)} data-testid="button-cancel-submit">Not yet</Button><Button onClick={()=>{submitVote(election.id,selected);setModal(false);setDone(true);setLocation('/voter/confirmation')}} data-testid="button-confirm-submit">Confirm ballot <Check className="h-4 w-4"/></Button></div></div></div>}</div></AppShell>; }
function Confirmation() { const {votedIds}=useStore();return <AppShell><div className="mx-auto max-w-3xl"><SectionTitle eyebrow="Private receipt" title="Your participation is recorded." description="Keep this reference for your own records. It confirms your ballot was received without revealing your candidate selection."/><div className="border bg-[hsl(var(--card))] p-7 shadow-[var(--shadow-sm)]"><div className="flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm text-[hsl(var(--muted-foreground))]">Ballot reference</p><p className="mt-2 font-mono text-2xl font-bold tracking-wide text-[hsl(var(--primary))]" data-testid="text-ballot-reference">VS-26-04A7-91K</p></div><Badge tone="success">Recorded securely</Badge></div><div className="mt-7 grid gap-4 border-t pt-5 sm:grid-cols-2"><div><p className="text-xs text-[hsl(var(--muted-foreground))]">Recorded</p><p className="mt-1 font-semibold">Today, 10:42 AM</p></div><div><p className="text-xs text-[hsl(var(--muted-foreground))]">Privacy status</p><p className="mt-1 font-semibold">Candidate choice hidden</p></div></div></div><div className="mt-6 flex items-start gap-3 border-l-4 border-[#37805b] bg-[#eef7f1] p-5 text-sm leading-6 text-[#2f6348]"><ShieldCheck className="mt-1 h-5 w-5 shrink-0"/><p><strong>Your vote remains private.</strong> VoteSecure only shows whether you have participated in an election, never who you chose. {votedIds.length>0&&'You can return to the directory to explore other elections.'}</p></div><Link href="/voter/elections" data-testid="link-confirmation-directory"><Button className="mt-8">Return to elections <ArrowRight className="h-4 w-4"/></Button></Link></div></AppShell>; }

function AdminDashboard() { const {elections,activities,voters}=useStore();const chart=[{name:'Jan 12',votes:32},{name:'Jan 15',votes:48},{name:'Jan 18',votes:41},{name:'Jan 21',votes:67},{name:'Jan 24',votes:58},{name:'Jan 27',votes:75},{name:'Jan 30',votes:81}]; return <AppShell admin><SectionTitle eyebrow="Administration" title="Stewardship dashboard." description="A quiet view of the health of your elections." action={<Button variant="secondary" onClick={()=>{}} data-testid="button-export-dashboard"><FileText className="h-4 w-4"/>Export report</Button>}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Registered voters" value="1,248" note="+8.2% from last month" icon={Users}/><StatCard label="Active elections" value={String(elections.filter(e=>e.status==='active').length).padStart(2,'0')} note="1 closing this week" icon={Vote}/><StatCard label="Overall turnout" value="65.4%" note="+4.1% from previous cycle" icon={TrendingUp} tone="green"/><StatCard label="Ballots recorded" value="1,309" note="Across all elections" icon={ClipboardCheck}/></div><div className="mt-8 grid gap-6 xl:grid-cols-[1.5fr_.5fr]"><div className="border bg-[hsl(var(--card))] p-6"><div className="mb-5 flex justify-between"><div><p className="label-caps text-[#28758f]">Participation</p><h2 className="mt-1 font-display text-2xl font-bold text-[hsl(var(--primary))]">Ballots over time</h2></div><Badge tone="success">Live data</Badge></div><div className="h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={chart}><CartesianGrid stroke="#e2e9ed" vertical={false}/><XAxis dataKey="name" tick={{fontSize:11}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize:11}} axisLine={false} tickLine={false}/><ChartTooltip/><Bar dataKey="votes" fill="#28758f" radius={[3,3,0,0]} /></BarChart></ResponsiveContainer></div></div><div className="border bg-[hsl(var(--primary))] p-6 text-white"><p className="label-caps text-[#a8cfdb]">Turnout snapshot</p><div className="mt-7 flex items-center justify-center"><div className="grid h-36 w-36 place-items-center rounded-full border-[14px] border-[#74b49a] border-l-[#37647e]"><div className="text-center"><p className="text-3xl font-bold">65.4%</p><p className="text-xs text-[#c6dae3]">turnout</p></div></div></div><p className="mt-7 text-sm leading-6 text-[#c6dae3]">Participation is trending above the last cycle. Keep the information clear and timely.</p></div></div><div className="mt-8 border bg-[hsl(var(--card))] p-6"><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-2xl font-bold text-[hsl(var(--primary))]">Recent activity</h2><Link href="/admin/elections" className="text-sm font-semibold text-[#28758f]" data-testid="link-admin-activity">View elections</Link></div>{activities.map(a=><ActivityRow activity={a} key={a.id}/>)}</div><p className="mt-5 text-xs text-[hsl(var(--muted-foreground))]">{voters.length} sample voter records loaded locally for this preview.</p></AppShell>; }

function AdminElections() { const {elections,deleteElection}=useStore();const [,setLocation]=useLocation();const [query,setQuery]=useState('');const [confirm,setConfirm]=useState<string|null>(null);const list=elections.filter(e=>e.title.toLowerCase().includes(query.toLowerCase()));return <AppShell admin><SectionTitle eyebrow="Manage elections" title="Election registry." description="Create, review, and maintain the public election calendar." action={<Button onClick={()=>setLocation('/admin/elections/create')} data-testid="button-create-election"><Plus className="h-4 w-4"/>Create election</Button>}/><div className="mb-4 flex items-center gap-3"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-2.5 h-4 w-4 text-[hsl(var(--muted-foreground))]"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search by election name" className="h-10 w-full rounded-md border bg-[hsl(var(--card))] pl-9 pr-3 text-sm" data-testid="input-admin-election-search"/></div><Button variant="secondary" data-testid="button-election-filter"><Filter className="h-4 w-4"/>Filter</Button></div><div className="overflow-x-auto border bg-[hsl(var(--card))]"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-[#f1f5f6] text-xs uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><tr><th className="px-5 py-4">Election</th><th className="px-5 py-4">Window</th><th className="px-5 py-4">Status</th><th className="px-5 py-4">Turnout</th><th className="px-5 py-4 text-right">Actions</th></tr></thead><tbody>{list.map(e=><tr className="border-t" key={e.id}><td className="px-5 py-5"><p className="font-semibold text-[hsl(var(--primary))]">{e.title}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{e.candidateIds.length} candidates</p></td><td className="px-5 py-5 text-[hsl(var(--muted-foreground))]">{e.startDate}<br/>{e.endDate}</td><td className="px-5 py-5"><Badge tone={e.status==='active'?'active':e.status==='ended'?'neutral':'blue'}>{e.status}</Badge></td><td className="px-5 py-5">{e.registeredVoters?`${Math.round(e.votes/e.registeredVoters*100)}%`:'—'}</td><td className="px-5 py-5"><div className="flex justify-end gap-1"><Link href={`/voter/elections/${e.id}`} data-testid={`link-admin-view-${e.id}`}><Button variant="ghost" className="px-2" aria-label="View election"><MoreHorizontal className="h-4 w-4"/></Button></Link><Link href={`/admin/elections/create?edit=${e.id}`} data-testid={`link-admin-edit-${e.id}`}><Button variant="ghost" className="px-2" aria-label="Edit election"><Edit3 className="h-4 w-4"/></Button></Link><Button variant="ghost" className="px-2 text-[#a53531]" onClick={()=>setConfirm(e.id)} aria-label="Delete election" data-testid={`button-delete-election-${e.id}`}><Trash2 className="h-4 w-4"/></Button></div></td></tr>)}</tbody></table></div>{confirm&&<Confirm title="Delete this election?" text="This removes the election from the local registry and cannot be undone." onCancel={()=>setConfirm(null)} onConfirm={()=>{deleteElection(confirm);setConfirm(null)}}/>}</AppShell>; }
function Confirm({title,text,onCancel,onConfirm}: {title:string;text:string;onCancel:()=>void;onConfirm:()=>void}) { return <div className="fixed inset-0 z-50 grid place-items-center bg-[#122b45]/50 p-5"><div className="w-full max-w-md border bg-[hsl(var(--card))] p-7 shadow-[var(--shadow-md)]"><p className="label-caps text-[#a53531]">Destructive action</p><h2 className="mt-2 font-display text-2xl font-bold text-[hsl(var(--primary))]">{title}</h2><p className="mt-4 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{text}</p><div className="mt-7 flex justify-end gap-3"><Button variant="ghost" onClick={onCancel} data-testid="button-cancel-delete">Cancel</Button><Button variant="danger" onClick={onConfirm} data-testid="button-confirm-delete">Delete</Button></div></div></div>; }
function ElectionForm() { const [,setLocation]=useLocation();const {elections,addElection,updateElection}=useStore();const params=new URLSearchParams(window.location.search);const editId=params.get('edit');const existing=elections.find(e=>e.id===editId);const [form,setForm]=useState({title:existing?.title||'',description:existing?.description||'',startDate:existing?.startDate||'2026-04-01',endDate:existing?.endDate||'2026-04-08',status:existing?.status||'upcoming'});const [error,setError]=useState('');const submit=(e:React.FormEvent)=>{e.preventDefault();if(!form.title||!form.description||form.startDate>=form.endDate){setError('Add a title, description, and valid date window.');return;}if(editId)updateElection(editId,form);else addElection({...form,candidateIds:[],votes:0,registeredVoters:0,voted:false});setLocation('/admin/elections');};return <AppShell admin><Link href="/admin/elections" className="mb-7 inline-flex items-center gap-2 text-sm font-semibold text-[#28758f]" data-testid="link-back-admin-elections"><ArrowLeft className="h-4 w-4"/>Back to elections</Link><SectionTitle eyebrow={editId?'Edit election':'New election'} title={editId?'Update election details':'Create an election'} description="Keep the public information concise and useful for voters."/><form onSubmit={submit} className="max-w-3xl border bg-[hsl(var(--card))] p-6 sm:p-8"><div className="grid gap-5"><label className="grid gap-2 text-sm font-semibold">Election title<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} className="h-12 rounded-md border px-3 font-normal" placeholder="e.g. Student Council Election 2026" data-testid="input-election-title"/></label><label className="grid gap-2 text-sm font-semibold">Description<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} className="min-h-28 rounded-md border p-3 font-normal" data-testid="input-election-description"/></label><div className="grid gap-5 sm:grid-cols-3"><label className="grid gap-2 text-sm font-semibold">Starts<input type="date" value={form.startDate} onChange={e=>setForm({...form,startDate:e.target.value})} className="h-11 rounded-md border px-3 font-normal" data-testid="input-election-start"/></label><label className="grid gap-2 text-sm font-semibold">Ends<input type="date" value={form.endDate} onChange={e=>setForm({...form,endDate:e.target.value})} className="h-11 rounded-md border px-3 font-normal" data-testid="input-election-end"/></label><label className="grid gap-2 text-sm font-semibold">Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value as Election['status']})} className="h-11 rounded-md border px-3 font-normal" data-testid="select-election-status"><option value="upcoming">Upcoming</option><option value="active">Active</option><option value="ended">Ended</option></select></label></div>{error&&<p className="text-sm text-[#a53531]" data-testid="status-election-error">{error}</p>}<div className="mt-4 flex justify-end gap-3 border-t pt-5"><Link href="/admin/elections" data-testid="link-cancel-election"><Button variant="ghost">Cancel</Button></Link><Button data-testid="button-save-election"><Check className="h-4 w-4"/>Save election</Button></div></div></form></AppShell>; }

function AdminCandidates() { const {candidates,elections,deleteCandidate,addCandidate,updateCandidate}=useStore();const [editing,setEditing]=useState<Candidate|null>(null);const [adding,setAdding]=useState(false);const [confirm,setConfirm]=useState<string|null>(null);const [search,setSearch]=useState('');const list=candidates.filter(c=>c.name.toLowerCase().includes(search.toLowerCase()));return <AppShell admin><SectionTitle eyebrow="Candidate registry" title="Candidates." description="Maintain the profiles voters use to make an informed choice." action={<Button onClick={()=>setAdding(true)} data-testid="button-add-candidate"><Plus className="h-4 w-4"/>Add candidate</Button>}/><div className="mb-5 max-w-sm relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-[hsl(var(--muted-foreground))]"/><input value={search} onChange={e=>setSearch(e.target.value)} className="h-10 w-full rounded border bg-[hsl(var(--card))] pl-9 text-sm" placeholder="Search candidates" data-testid="input-candidate-search"/></div><div className="grid gap-3">{list.map(c=><div key={c.id} className="flex flex-col gap-4 border bg-[hsl(var(--card))] p-5 sm:flex-row sm:items-center"><div className="grid h-12 w-12 shrink-0 place-items-center rounded-full text-sm font-bold text-white" style={{backgroundColor:c.color}}>{c.name.split(' ').map(n=>n[0]).join('')}</div><div className="min-w-0 flex-1"><p className="font-semibold text-[hsl(var(--primary))]">{c.name}</p><p className="text-sm text-[#28758f]">{c.party} <span className="text-[hsl(var(--muted-foreground))]">· {elections.find(e=>e.id===c.electionId)?.title}</span></p><p className="mt-1 truncate text-sm text-[hsl(var(--muted-foreground))]">{c.description}</p></div><div className="flex gap-1"><Button variant="ghost" onClick={()=>setEditing(c)} data-testid={`button-edit-candidate-${c.id}`}><Edit3 className="h-4 w-4"/>Edit</Button><Button variant="ghost" className="text-[#a53531]" onClick={()=>setConfirm(c.id)} data-testid={`button-delete-candidate-${c.id}`}><Trash2 className="h-4 w-4"/>Delete</Button></div></div>)}</div>{(adding||editing)&&<CandidateModal initial={editing} elections={elections} onClose={()=>{setAdding(false);setEditing(null)}} onSave={data=>{if(editing)updateCandidate(editing.id,data);else addCandidate(data);setAdding(false);setEditing(null)}}/>}{confirm&&<Confirm title="Delete this candidate?" text="The candidate profile will be removed from the local registry." onCancel={()=>setConfirm(null)} onConfirm={()=>{deleteCandidate(confirm);setConfirm(null)}}/>}</AppShell>; }
function CandidateModal({initial,elections,onClose,onSave}: {initial:Candidate|null;elections:Election[];onClose:()=>void;onSave:(data:Omit<Candidate,'id'>)=>void}) { const [f,setF]=useState({name:initial?.name||'',party:initial?.party||'',description:initial?.description||'',electionId:initial?.electionId||elections[0].id,color:initial?.color||'#287fa6'});return <div className="fixed inset-0 z-50 grid place-items-center bg-[#122b45]/50 p-5"><div className="max-h-[90dvh] w-full max-w-lg overflow-auto border bg-[hsl(var(--card))] p-7"><div className="flex justify-between"><div><p className="label-caps text-[#28758f]">Candidate profile</p><h2 className="mt-2 font-display text-2xl font-bold text-[hsl(var(--primary))]">{initial?'Edit candidate':'Add candidate'}</h2></div><button onClick={onClose} data-testid="button-close-candidate"><X className="h-5 w-5"/></button></div><div className="mt-6 grid gap-4"><label className="grid gap-2 text-sm font-semibold">Name<input value={f.name} onChange={e=>setF({...f,name:e.target.value})} className="h-11 rounded border px-3 font-normal" data-testid="input-candidate-name"/></label><label className="grid gap-2 text-sm font-semibold">Election<select value={f.electionId} onChange={e=>setF({...f,electionId:e.target.value})} className="h-11 rounded border px-3 font-normal" data-testid="select-candidate-election">{elections.map(e=><option key={e.id} value={e.id}>{e.title}</option>)}</select></label><label className="grid gap-2 text-sm font-semibold">Affiliation<input value={f.party} onChange={e=>setF({...f,party:e.target.value})} className="h-11 rounded border px-3 font-normal" data-testid="input-candidate-party"/></label><label className="grid gap-2 text-sm font-semibold">Short profile<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})} className="min-h-24 rounded border p-3 font-normal" data-testid="input-candidate-description"/></label><div><p className="text-sm font-semibold">Photo</p><button type="button" className="mt-2 flex w-full items-center gap-3 border border-dashed p-4 text-left text-sm text-[hsl(var(--muted-foreground))]" data-testid="button-upload-photo"><span className="grid h-9 w-9 place-items-center rounded bg-[#e3f0f5]"><Plus className="h-4 w-4 text-[#28758f]"/></span>Upload a profile photo <span className="ml-auto text-xs">JPG or PNG</span></button></div></div><div className="mt-7 flex justify-end gap-3 border-t pt-5"><Button variant="ghost" onClick={onClose} data-testid="button-cancel-candidate">Cancel</Button><Button onClick={()=>f.name&&f.party&&onSave(f)} disabled={!f.name||!f.party} data-testid="button-save-candidate">Save profile</Button></div></div></div>; }

function AdminVoters() { const {voters}=useStore();const [q,setQ]=useState('');const [status,setStatus]=useState('all');const list=voters.filter(v=>(status==='all'||(status==='voted'?v.voted:!v.voted))&&(v.name+v.email).toLowerCase().includes(q.toLowerCase()));return <AppShell admin><SectionTitle eyebrow="Voter register" title="Voters." description="Manage eligibility and participation status without exposing ballot choices."/><div className="mb-5 flex max-w-2xl gap-3"><div className="relative flex-1"><Search className="absolute left-3 top-2.5 h-4 w-4 text-[hsl(var(--muted-foreground))]"/><input value={q} onChange={e=>setQ(e.target.value)} className="h-10 w-full rounded border bg-[hsl(var(--card))] pl-9 text-sm" placeholder="Search by name or email" data-testid="input-voter-search"/></div><select value={status} onChange={e=>setStatus(e.target.value)} className="h-10 rounded border bg-[hsl(var(--card))] px-3 text-sm" data-testid="select-voter-status"><option value="all">All voters</option><option value="voted">Voted</option><option value="pending">Not voted</option></select></div><div className="overflow-x-auto border bg-[hsl(var(--card))]"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-[#f1f5f6] text-xs uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><tr><th className="px-5 py-4">Voter</th><th className="px-5 py-4">Mobile</th><th className="px-5 py-4">Registered</th><th className="px-5 py-4">Participation</th></tr></thead><tbody>{list.map(v=><tr className="border-t" key={v.id}><td className="px-5 py-4"><p className="font-semibold text-[hsl(var(--primary))]">{v.name}</p><p className="text-xs text-[hsl(var(--muted-foreground))]">{v.email}</p></td><td className="px-5 py-4 text-[hsl(var(--muted-foreground))]">{v.mobile}</td><td className="px-5 py-4 text-[hsl(var(--muted-foreground))]">{v.registrationDate}</td><td className="px-5 py-4"><Badge tone={v.voted?'success':'neutral'}>{v.voted?'Voted':'Not voted'}</Badge></td></tr>)}</tbody></table></div><p className="mt-4 flex items-center gap-2 text-xs text-[hsl(var(--muted-foreground))]"><ShieldCheck className="h-4 w-4 text-[#37805b]"/>Candidate choices are never stored in this register.</p></AppShell>; }

function AdminResults() { const {elections,candidates,results}=useStore();const [id,setId]=useState(elections[2].id);const election=elections.find(e=>e.id===id)!;const rs=results[id]||[];const data=rs.map(r=>({...r,name:candidates.find(c=>c.id===r.candidateId)?.name||'Candidate'}));return <AppShell admin><SectionTitle eyebrow="Results & reporting" title="Results." description="Monitor participation live. Publish final outcomes when an election has closed." action={<select value={id} onChange={e=>setId(e.target.value)} className="h-11 rounded border bg-[hsl(var(--card))] px-3 text-sm" data-testid="select-results-election">{elections.map(e=><option key={e.id} value={e.id}>{e.title}</option>)}</select>}/>{election.status!=='ended'?<div className="border bg-[#eef6f7] p-8"><div className="flex items-start gap-4"><TrendingUp className="mt-1 h-6 w-6 text-[#28758f]"/><div><h2 className="font-display text-2xl font-bold text-[hsl(var(--primary))]">Participation is live.</h2><p className="mt-2 max-w-2xl leading-7 text-[hsl(var(--muted-foreground))]">Candidate-level results stay private while this election is active. You can see turnout progress without influencing an open ballot.</p></div></div><div className="mt-8 grid gap-4 sm:grid-cols-3"><StatCard label="Ballots recorded" value={String(election.votes)} note={`of ${election.registeredVoters} registered`} icon={ClipboardCheck}/><StatCard label="Turnout" value={`${Math.round(election.votes/election.registeredVoters*100)}%`} note="Updated moments ago" icon={TrendingUp} tone="green"/><StatCard label="Time remaining" value="3 days" note={`Closes ${election.endDate}`} icon={Clock3}/></div></div>:<><div className="mb-6 grid gap-4 sm:grid-cols-3"><StatCard label="Final ballots" value={String(election.votes)} note={`${election.registeredVoters} registered voters`} icon={ClipboardCheck}/><StatCard label="Final turnout" value={`${Math.round(election.votes/election.registeredVoters*100)}%`} note="Election closed" icon={TrendingUp} tone="green"/><StatCard label="Candidates" value={String(data.length)} note="Final count published" icon={Users}/></div><div className="grid gap-6 lg:grid-cols-2"><div className="border bg-[hsl(var(--card))] p-6"><h2 className="font-display text-2xl font-bold text-[hsl(var(--primary))]">Final count</h2><div className="mt-6 h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={data} layout="vertical" margin={{left:10,right:20}}><CartesianGrid stroke="#e2e9ed" horizontal={false}/><XAxis type="number" hide/><YAxis type="category" dataKey="name" width={90} tick={{fontSize:11}}/><ChartTooltip/><Bar dataKey="votes" fill="#28758f" radius={[0,3,3,0]}>{data.map((d,i)=><Cell key={d.candidateId} fill={['#287fa6','#397c68','#bd7b43','#6c6f9d'][i%4]}/>)}</Bar></BarChart></ResponsiveContainer></div></div><div className="border bg-[hsl(var(--card))] p-6"><h2 className="font-display text-2xl font-bold text-[hsl(var(--primary))]">Share of ballots</h2><div className="mt-5 h-72"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data} dataKey="votes" nameKey="name" innerRadius={65} outerRadius={100} paddingAngle={3}>{data.map((d,i)=><Cell key={d.candidateId} fill={['#287fa6','#397c68','#bd7b43','#6c6f9d'][i%4]}/>)}</Pie><ChartTooltip/><Legend verticalAlign="bottom" height={36}/></PieChart></ResponsiveContainer></div></div></div></>}</AppShell>; }

function NotFound() { return <PublicLayout><div className="mx-auto max-w-2xl px-5 py-28 text-center"><p className="label-caps text-[#28758f]">Page not found</p><h1 className="mt-3 font-display text-5xl font-bold text-[hsl(var(--primary))]">That path is not on the ballot.</h1><p className="mt-4 text-[hsl(var(--muted-foreground))]">The page may have moved, or the address may be incomplete.</p><Link href="/" data-testid="link-notfound-home"><Button className="mt-8">Return home</Button></Link></div></PublicLayout>; }

function Provider() { const [elections,setElections]=useState(seedElections);const [candidates,setCandidates]=useState(seedCandidates);const [voters]=useState(seedVoters);const [activities]=useState(seedActivities);const [results]=useState(seedResults);const [votedIds,setVotedIds]=useState<string[]>([]);const store:Store={elections,candidates,voters,activities,results,votedIds,addElection:data=>setElections(es=>[...es,{id:`e${Date.now()}`,title:data.title||'Untitled election',description:data.description||'',startDate:data.startDate||'',endDate:data.endDate||'',status:data.status||'upcoming',candidateIds:data.candidateIds||[],votes:0,registeredVoters:0,voted:false}]),updateElection:(id,data)=>setElections(es=>es.map(e=>e.id===id?{...e,...data}:e)),deleteElection:id=>setElections(es=>es.filter(e=>e.id!==id)),addCandidate:data=>setCandidates(cs=>[...cs,{...data,id:`c${Date.now()}`}]),updateCandidate:(id,data)=>setCandidates(cs=>cs.map(c=>c.id===id?{...c,...data}:c)),deleteCandidate:id=>setCandidates(cs=>cs.filter(c=>c.id!==id)),submitVote:(id)=>setVotedIds(ids=>ids.includes(id)?ids:[...ids,id])};return <StoreContext.Provider value={store}><Router/></StoreContext.Provider>; }
function RoutedErrorBoundary({children}:{children:ReactNode}) { const [location]=useLocation();return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function Router() { return <RoutedErrorBoundary><Switch><Route path="/" component={Home}/><Route path="/login"><Login/></Route><Route path="/register" component={Register}/><Route path="/admin/login"><Login admin/></Route><Route path="/voter/dashboard" component={VoterDashboard}/><Route path="/voter/elections" component={ElectionDirectory}/><Route path="/voter/elections/:id" component={ElectionDetails}/><Route path="/voter/vote/:id" component={VotePage}/><Route path="/voter/confirmation" component={Confirmation}/><Route path="/admin/dashboard" component={AdminDashboard}/><Route path="/admin/elections" component={AdminElections}/><Route path="/admin/elections/create" component={ElectionForm}/><Route path="/admin/candidates" component={AdminCandidates}/><Route path="/admin/voters" component={AdminVoters}/><Route path="/admin/results" component={AdminResults}/><Route component={NotFound}/></Switch></RoutedErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><Provider/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>; }
export default App;